        return parser;
    }







    @Test
    public void testGetIntValue_BranchCoverage_CannotConvert() throws Exception {
        // To trigger the 'if (!node.canConvertToInt())' branch
        // We need a NumericNode where canConvertToInt returns false.
        // Note: In standard Jackson, most NumericNodes return true for canConvertToInt 
        // unless they are exceptionally large or specific types.

        NumericNode mockNode = Mockito.mock(NumericNode.class);
        when(mockNode.canConvertToInt()).thenReturn(false);
        when(mockNode.intValue()).thenReturn(0);

        TreeTraversingParser spyParser = Mockito.spy(new TreeTraversingParser(mockNode));
        when(spyParser.currentNumericNode()).thenReturn(mockNode);

        // This tests the empty block ';' in the if statement for branch coverage
        int result = spyParser.getIntValue();
        assertEquals(0, result);
    }




}

